// cd packages/core && npx vitest run test/review-tmp/snapgene-robustness-quadratic.test.ts
import { describe, expect, it } from 'vitest';
import { makeFeature, makeRecord } from '../../src/seq/features';
import { parseSnapGene, writeSnapGene } from '../../src/io/snapgene';

const enc = (s: string) => new TextEncoder().encode(s);
function packet(type: number, text: string, out: number[]): void {
  const body = enc(text);
  out.push(type, (body.length >>> 24) & 255, (body.length >>> 16) & 255, (body.length >>> 8) & 255, body.length & 255);
  for (const b of body) out.push(b);
}
/** A minimal SnapGene file (cookie + 4 bp DNA) followed by the given XML packets. */
function snapgene(...xml: Array<[number, string]>): Uint8Array {
  const out: number[] = [0x09, 0, 0, 0, 14, ...enc('SnapGene'), 0, 1, 0, 15, 0, 19, 0x00, 0, 0, 0, 5, 0x02, ...enc('ACGT')];
  for (const [type, text] of xml) packet(type, text, out);
  return Uint8Array.from(out);
}
function timed(data: Uint8Array): number {
  const started = performance.now();
  const result = parseSnapGene(data, { fileName: 'crafted.dna' });
  expect(result.records).toHaveLength(1);
  return performance.now() - started;
}

// For scale: the 11.3 MB SnapGene file of E. coli U00096.3 (9285 features) is read in ~0.5 s.
describe('SnapGene reader/writer: linear time on crafted input', () => {
  it('reads a 1.05 MB file whose Description is "<!--" x 150 000 in < 2 s (looksLikeHtml)', () => {
    expect(timed(snapgene([0x06, `<Notes><Description>${'&lt;!--'.repeat(150_000)}</Description></Notes>`]))).toBeLessThan(2000);
  }, 120_000);

  it('writes a record whose /note is "<!--" x 150 000 in < 2 s (plainToRichText -> looksLikeHtml)', () => {
    const record = makeRecord({ seq: 'ACGTACGTAC', features: [makeFeature({ type: 'misc_feature', name: 'x', segments: [{ start: 0, end: 4 }], qualifiers: [{ key: 'note', value: '<!--'.repeat(150_000) }] })] });
    const started = performance.now();
    writeSnapGene(record, { now: new Date(Date.UTC(2026, 0, 1)) });
    expect(performance.now() - started).toBeLessThan(2000);
  }, 120_000);

  it('reads a 358 KB file made of 10 000 small Notes packets in < 2 s (notesExtras re-spread per packet)', () => {
    const packets: Array<[number, string]> = Array.from({ length: 10_000 }, (_, i) => [0x06, `<Notes><F${i}>v</F${i}></Notes>`]);
    expect(timed(snapgene(...packets))).toBeLessThan(2000);
  }, 120_000);

  it('reads a 1.3 MB file with 60 000 <Comments> elements in < 2 s (meta.comments re-spread per element)', () => {
    expect(timed(snapgene([0x06, `<Notes>${'<Comments>c</Comments>'.repeat(60_000)}</Notes>`]))).toBeLessThan(2000);
  }, 120_000);

  it('reads a 1.4 MB file whose Comments start with 200 000 <br> in < 2 s (lines.shift() loop in htmlToText)', () => {
    expect(timed(snapgene([0x06, `<Notes><Comments>&lt;html>&lt;body>${'&lt;br>'.repeat(200_000)}text&lt;/body>&lt;/html></Comments></Notes>`]))).toBeLessThan(2000);
  }, 120_000);
});

