  const file = concat(
    packet(0x09, concat(utf8('SnapGene'), new Uint8Array([0, 1, 0, 15, 0, 19]))),
    packet(0x00, concat(new Uint8Array([0x02]), utf8('ATGNCATAA'))),
    packet(0x0a, utf8('<?xml version="1.0"?><Features nextValidID="1"><Feature recentID="0" name="orf" directionality="1" type="CDS" allowSegmentOverlaps="0" consecutiveTranslationNumbering="1" hitsStopCodon="1"><Segment range="1-9" color="#993366" type="standard" translated="1"/><Q name="translation"><V text="M?*"/></Q></Feature></Features>')),
  );
  const record = parseSnapGene(file).records[0];
  const cds = record.features[0];
  expect(translateFeature(record, cds)).toBe('MX*');            // passes: HHereditas' own translation uses X
